<?php require_once __DIR__ . '/_logistics_common.php';
function logi_insert_dynamic_move(PDO $pdo,string $table,array $payload): void { $filtered=[]; foreach($payload as $column=>$value){ if(logi_col_exists($pdo,$table,$column))$filtered[$column]=$value; } if(!$filtered)return; $cols=array_keys($filtered); $marks=array_map(fn($c)=>':'.$c,$cols); $pdo->prepare('INSERT INTO `'.$table.'` (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',$marks).')')->execute($filtered); }
$items=logi_options_stock($pdo); $chantiers=logi_chantiers($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){ $itemId=(int)($_POST['item_id']??0); $qty=max(0,(float)($_POST['quantity']??0)); $type=$_POST['movement_type']??'in'; if($itemId>0 && $qty>0){ $signed=in_array($type,['out','affectation'],true)?-$qty:$qty; $pdo->beginTransaction(); logi_insert_dynamic_move($pdo,'logistics_stock_movements',['item_id'=>$itemId,'movement_type'=>$type,'quantity'=>$qty,'site_label'=>$_POST['site_label']??null,'reason'=>$_POST['reason']??null,'movement_at'=>$_POST['movement_at']?:date('Y-m-d H:i:s'),'notes'=>$_POST['reason']??null,'created_at'=>$_POST['movement_at']?:date('Y-m-d H:i:s')]); $movementId=(int)$pdo->lastInsertId(); $pdo->prepare('UPDATE logistics_stock_items SET current_quantity=current_quantity+?, current_stock=current_stock+? WHERE id=?')->execute([$signed,$signed,$itemId]); $pdo->commit(); $label=trim($type.' stock #'.$itemId.' ('.$qty.')'); logi_notify_asset_event($pdo,'stock_movement_created',['entity_type'=>'stock_movement','entity_id'=>$movementId,'entity_label'=>$label,'site_label'=>$_POST['site_label']??null]); logi_audit($pdo,'create_stock_movement','logistics_stock_movement',$movementId,$label,['item_id'=>$itemId,'quantity'=>$qty,'movement_type'=>$type]); } logi_redirect('stock.php?ok=1'); }
logi_page_start('Ajouter un mouvement stock','Formulaire dedie entree, sortie ou affectation.');
logi_card_open('Mouvement de stock','Entree, sortie ou affectation chantier'); ?>
<form method="post" class="grid md:grid-cols-2 gap-5"><?= logi_search_select('Article','item_id',logi_search_options($items,'id','label','Selectionner'),'','required','Rechercher un article') ?><?= logi_select('Type','movement_type',['in'=>'Entree','out'=>'Sortie','correction'=>'Correction +','affectation'=>'Affectation chantier']) ?><?= logi_input('Quantite','quantity','0','number','step="0.01" required') ?><?= logi_chantier_search_input('Chantier / destination','site_label',$chantiers) ?><?= logi_input('Date mouvement','movement_at','','datetime-local') ?><div class="md:col-span-2"><?= logi_textarea('Motif','reason') ?></div><div class="md:col-span-2"><?= logi_submit('Enregistrer mouvement') ?></div></form>
<div class="mt-4"><a href="stock.php" class="font-semibold text-orange-600">Retour au listing</a></div>
<?php logi_card_close(); logi_page_end();
